export function yardApproaches (lines) {
  if (!Array.isArray(lines)) return 0
  let n = 0
  for (const l of lines) {
    if (typeof l === 'string' && YARD_APPROACH_RE.test(l)) n++
  }
  return n
}

export function yardApproachTrendConsistent (e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return false
  const faceOk = (s) => {
    if (!s || typeof s !== 'object' || Array.isArray(s)) return false
    return Number.isInteger(s.yardApproaches) && s.yardApproaches >= 0
  }
  return faceOk(e.back) && faceOk(e.prev) && faceOk(e.cur)
}

